members.products.graphql:
extend schema @link(url: "https://specs.apollo.dev/federation/v2.3", import: ["@key"])

type Query {
  topProducts: [Product!]
}

type Product @key(fields: "id") {
  id: ID!
  weightGrams: Int
}

members.inventory.graphql:
extend schema @link(url: "https://specs.apollo.dev/federation/v2.3", import: ["@key"])

type Query {
  inStock: [Product!]
}

type Product @key(fields: "id") {
  id: ID!
  weightGrams: Int
  unitsInStock: Int!
}
